+ export function cloneDoc(doc: StudioDoc): StudioDoc {
+   return {
+     ...doc,
+     pages: doc.pages.map(p => ({ ...p, order: [...p.order] })),
+     nodes: { ...doc.nodes },
+     assets: [...doc.assets],
+     chat: [...doc.chat],
+     agents: [...doc.agents]
+   }
+ }
