+   direction: 'none' | 'row' | 'column'
+   gap: number
+   padding: [number, number, number, number]
+   align: 'start' | 'center' | 'end'
+   justify: 'start' | 'center' | 'end' | 'between'
+   wrap: boolean
+   sizeW: Sizing
+   sizeH: Sizing
+ }
+ 
+ export interface TypeStyle {
+   family: string
+   size: number
+   weight: number
+   lineHeight: number
+   spacing: number
+   align: 'left' | 'center' | 'right'
+   color: string
+   transform: 'none' | 'upper' | 'lower'
+   italic: boolean
+ }
+ 
+ export type Corner = [number, number, number, number]
+ 
+ export interface DesignNodeProps {
+   w: number
+   h: number
+   name: string
+   radius: Corner
+   fills: Paint[]
+   strokes: Stroke[]
+   effects: Effect[]
+   layout: Layout
+   text: string
+   type: TypeStyle
+   clip: boolean
+   mask: boolean
+   blend: string
+   component: string
+   instanceOf: string
+ }
+ 
+ export const NO_LAYOUT: Layout = {
+   direction: 'none',
+   gap: 0,
+   padding: [0, 0, 0, 0],
+   align: 'start',
+   justify: 'start',
+   wrap: false,
+   sizeW: 'fixed',
+   sizeH: 'fixed'
+ }
+ 
+ export const BASE_TYPE: TypeStyle = {
+   family: 'sans',
+   size: 14,
+   weight: 400,
+   lineHeight: 1.5,
+   spacing: 0,
+   align: 'left',
+   color: '#ffffff',
+   transform: 'none',
+   italic: false
+ }
+ 
+ export function solid(color: string): Paint {
+   return { type: 'solid', color, opacity: 1 }
+ }
+ 
+ export function corner(value: number): Corner {
+   return [value, value, value, value]
+ }
+ 
+ export function nodeDefaults(): DesignNodeProps {
+   return {
+     w: 200,
+     h: 120,
+     name: 'Frame',
+     radius: corner(0),
+     fills: [solid('#222222')],
+     strokes: [],
+     effects: [],
+     layout: { ...NO_LAYOUT },
+     text: '',
+     type: { ...BASE_TYPE },
+     clip: false,
+     mask: false,
+     blend: 'normal',
+     component: '',
+     instanceOf: ''
+   }
+ }
+ 
+ const HEX = /^#[0-9a-fA-F]{6}$|^#[0-9a-fA-F]{8}$/
+ 
+ export function isHex(value: unknown): value is string {
+   return typeof value === 'string' && HEX.test(value)
+ }
+ 
+ function clamp(value: unknown, low: number, high: number, fallback: number): number {
+   return typeof value === 'number' && isFinite(value) ? Math.min(high, Math.max(low, value)) : fallback
+ }
+ 
+ function cleanStops(value: unknown): PaintStop[] {
+   if (!Array.isArray(value)) return []
+   const stops = value
+     .filter(stop => isHex((stop as PaintStop)?.color))
+     .map(stop => ({ color: (stop as PaintStop).color, at: clamp((stop as PaintStop).at, 0, 1, 0) }))
+   return stops.length >= 2 ? stops : []
+ }
+ 
+ export function cleanPaint(value: unknown): Paint | null {
+   const paint = value as Partial<Paint> & { type?: string }
+   if (!paint || typeof paint !== 'object') return null
+   const opacity = clamp((paint as { opacity?: number }).opacity, 0, 1, 1)
+   if (paint.type === 'solid') {
+     return isHex((paint as { color?: string }).color) ? { type: 'solid', color: (paint as { color: string }).color, opacity } : null
+   }
+   if (paint.type === 'linear') {
+     const stops = cleanStops((paint as { stops?: unknown }).stops)
+     if (stops.length === 0) return null
+     return { type: 'linear', angle: clamp((paint as { angle?: number }).angle, -360, 360, 180), stops, opacity }
+   }
+   if (paint.type === 'radial') {
+     const stops = cleanStops((paint as { stops?: unknown }).stops)
+     return stops.length === 0 ? null : { type: 'radial', stops, opacity }
+   }
+   if (paint.type === 'glass') {
+     const tint = (paint as { tint?: string }).tint
+     return {
+       type: 'glass',
+       tint: isHex(tint) ? tint : '#ffffff14',
+       blur: clamp((paint as { blur?: number }).blur, 0, 200, 24),
+       opacity
+     }
+   }
+   return null
+ }
+ 
+ export function cleanStroke(value: unknown): Stroke | null {
+   const stroke = value as Partial<Stroke>
+   if (!stroke || typeof stroke !== 'object' || !isHex(stroke.color)) return null
+   return {
+     color: stroke.color,
+     weight: clamp(stroke.weight, 0, 200, 1),
+     align: stroke.align === 'center' || stroke.align === 'outside' ? stroke.align : 'inside',
+     style: stroke.style === 'dashed' || stroke.style === 'dotted' ? stroke.style : 'solid'
+   }
+ }
+ 
+ export function cleanEffect(value: unknown): Effect | null {
+   const effect = value as Partial<Effect> & { type?: string }
+   if (!effect || typeof effect !== 'object') return null
+   if (effect.type === 'layer-blur' || effect.type === 'background-blur') {
+     return { type: effect.type, blur: clamp((effect as { blur?: number }).blur, 0, 200, 8) }
+   }
+   if (effect.type === 'shadow' || effect.type === 'inner-shadow') {
+     const shadow = effect as Partial<Extract<Effect, { type: 'shadow' }>>
+     return {
+       type: effect.type,
+       x: clamp(shadow.x, -400, 400, 0),
+       y: clamp(shadow.y, -400, 400, 4),
+       blur: clamp(shadow.blur, 0, 400, 12),
+       spread: clamp(shadow.spread, -400, 400, 0),
+       color: isHex(shadow.color) ? shadow.color : '#00000040'
+     }
+   }
+   return null
+ }
+ 
+ export function cleanCorner(value: unknown): Corner | null {
+   if (typeof value === 'number' && isFinite(value)) return corner(Math.max(0, value))
+   if (!Array.isArray(value) || value.length !== 4) return null
+   return value.map(part => clamp(part, 0, 9999, 0)) as Corner
+ }
+ 
+ export function cleanLayout(value: unknown): Layout | null {
+   const layout = value as Partial<Layout>
+   if (!layout || typeof layout !== 'object') return null
+   const direction = layout.direction
+   const padding = Array.isArray(layout.padding)
+     ? (layout.padding.map(part => clamp(part, 0, 9999, 0)) as Corner)
+     : typeof layout.padding === 'number'
+       ? corner(layout.padding)
+       : NO_LAYOUT.padding
+   const sizing = (value: unknown, fallback: Sizing): Sizing =>
+     value === 'hug' || value === 'fill' || value === 'fixed' ? value : fallback
+   return {
+     direction: direction === 'row' || direction === 'column' ? direction : 'none',
+     gap: clamp(layout.gap, 0, 9999, 0),
+     padding: padding.length === 4 ? padding : NO_LAYOUT.padding,
+     align: layout.align === 'center' || layout.align === 'end' ? layout.align : 'start',
+     justify:
+       layout.justify === 'center' || layout.justify === 'end' || layout.justify === 'between'
+         ? layout.justify
+         : 'start',
+     wrap: layout.wrap === true,
+     sizeW: sizing(layout.sizeW, 'fixed'),
+     sizeH: sizing(layout.sizeH, 'fixed')
+   }
+ }
+ 
+ export function cleanType(value: unknown): TypeStyle | null {
+   const type = value as Partial<TypeStyle>
+   if (!type || typeof type !== 'object') return null
+   return {
+     family: typeof type.family === 'string' && type.family ? type.family : BASE_TYPE.family,
+     size: clamp(type.size, 1, 800, BASE_TYPE.size),
+     weight: clamp(type.weight, 100, 900, BASE_TYPE.weight),
+     lineHeight: clamp(type.lineHeight, 0.5, 4, BASE_TYPE.lineHeight),
+     spacing: clamp(type.spacing, -20, 100, BASE_TYPE.spacing),
+     align: type.align === 'center' || type.align === 'right' ? type.align : 'left',
+     color: isHex(type.color) ? type.color : BASE_TYPE.color,
+     transform: type.transform === 'upper' || type.transform === 'lower' ? type.transform : 'none',
+     italic: type.italic === true
+   }
+ }
+

+ import type { CSSProperties } from 'react'
+ import type { DesignNodeProps, Effect, Layout, Paint, Stroke, TypeStyle } from '../../../shared/designNode'
+ 
+ const FAMILIES: Record<string, string> = {
+   sans: 'ui-sans-serif, system-ui, -apple-system, "SF Pro Text", "Segoe UI", sans-serif',
+   serif: 'ui-serif, Georgia, "Times New Roman", serif',
+   mono: '"Cascadia Mono", ui-monospace, "SF Mono", Menlo, monospace'
+ }
+ 
+ const ALIGN: Record<string, string> = { start: 'flex-start', center: 'center', end: 'flex-end' }
+ const JUSTIFY: Record<string, string> = { ...ALIGN, between: 'space-between' }
+ 
+ function withOpacity(color: string, opacity: number): string {
+   if (opacity >= 1) return color
+   const alpha = Math.round(Math.min(1, Math.max(0, opacity)) * 255)
+     .toString(16)
+     .padStart(2, '0')
+   return color.length === 9 ? color.slice(0, 7) + alpha : color + alpha
+ }
+ 
+ function stopList(stops: Array<{ color: string; at: number }>): string {
+   return stops
+     .slice()
+     .sort((a, b) => a.at - b.at)
+     .map(stop => `${stop.color} ${Math.round(stop.at * 100)}%`)
+     .join(', ')
+ }
+ 
+ function paintLayer(paint: Paint): string | null {
+   if (paint.type === 'solid') return `linear-gradient(${withOpacity(paint.color, paint.opacity)}, ${withOpacity(paint.color, paint.opacity)})`
+   if (paint.type === 'linear') return `linear-gradient(${paint.angle}deg, ${stopList(paint.stops)})`
+   if (paint.type === 'radial') return `radial-gradient(circle at 50% 50%, ${stopList(paint.stops)})`
+   if (paint.type === 'glass') return `linear-gradient(${withOpacity(paint.tint, paint.opacity)}, ${withOpacity(paint.tint, paint.opacity)})`
+   return null
+ }
+ 
+ function strokeShadows(strokes: Stroke[]): string[] {
+   const out: string[] = []
+   for (const stroke of strokes) {
+     if (stroke.weight <= 0 || stroke.style !== 'solid') continue
+     if (stroke.align === 'inside') out.push(`inset 0 0 0 ${stroke.weight}px ${stroke.color}`)
+     else if (stroke.align === 'outside') out.push(`0 0 0 ${stroke.weight}px ${stroke.color}`)
+     else {
+       const half = stroke.weight / 2
+       out.push(`inset 0 0 0 ${half}px ${stroke.color}`, `0 0 0 ${half}px ${stroke.color}`)
+     }
+   }
+   return out
+ }
+ 
+ function dashedStroke(strokes: Stroke[]): CSSProperties {
+   const dashed = strokes.find(stroke => stroke.style !== 'solid' && stroke.weight > 0)
+   if (!dashed) return {}
+   return { outline: `${dashed.weight}px ${dashed.style} ${dashed.color}`, outlineOffset: `-${dashed.weight}px` }
+ }
+ 
+ function effectStyle(effects: Effect[]): { shadows: string[]; filter: string[]; backdrop: string[] } {
+   const shadows: string[] = []
+   const filter: string[] = []
+   const backdrop: string[] = []
+   for (const effect of effects) {
+     if (effect.type === 'shadow') shadows.push(`${effect.x}px ${effect.y}px ${effect.blur}px ${effect.spread}px ${effect.color}`)
+     else if (effect.type === 'inner-shadow')
+       shadows.push(`inset ${effect.x}px ${effect.y}px ${effect.blur}px ${effect.spread}px ${effect.color}`)
+     else if (effect.type === 'layer-blur') filter.push(`blur(${effect.blur}px)`)
+     else backdrop.push(`blur(${effect.blur}px)`)
+   }
+   return { shadows, filter, backdrop }
+ }
+ 
+ export function layoutStyle(layout: Layout): CSSProperties {
+   if (layout.direction === 'none') return {}
+   const [top, right, bottom, left] = layout.padding
+   return {
+     display: 'flex',
+     flexDirection: layout.direction === 'row' ? 'row' : 'column',
+     gap: `${layout.gap}px`,
+     padding: `${top}px ${right}px ${bottom}px ${left}px`,
+     alignItems: ALIGN[layout.align],
+     justifyContent: JUSTIFY[layout.justify],
+     flexWrap: layout.wrap ? 'wrap' : 'nowrap'
+   }
+ }
+ 
+ export function textStyle(type: TypeStyle): CSSProperties {
+   return {
+     fontFamily: FAMILIES[type.family] ?? type.family,
+     fontSize: `${type.size}px`,
+     fontWeight: type.weight,
+     lineHeight: type.lineHeight,
+     letterSpacing: `${type.spacing}px`,
+     textAlign: type.align,
+     color: type.color,
+     textTransform: type.transform === 'upper' ? 'uppercase' : type.transform === 'lower' ? 'lowercase' : 'none',
+     fontStyle: type.italic ? 'italic' : 'normal'
+   }
+ }
+ 
+ export function nodeStyle(props: DesignNodeProps): CSSProperties {
+   const layers = props.fills.map(paintLayer).filter((layer): layer is string => layer !== null)
+   const { shadows, filter, backdrop } = effectStyle(props.effects)
+   const glass = props.fills.find(paint => paint.type === 'glass')
+   if (glass && glass.type === 'glass') backdrop.push(`blur(${glass.blur}px)`, 'saturate(1.6)')
+   const [tl, tr, br, bl] = props.radius
+   const boxShadow = [...strokeShadows(props.strokes), ...shadows]
+   return {
+     borderRadius: `${tl}px ${tr}px ${br}px ${bl}px`,
+     backgroundImage: layers.length > 0 ? layers.join(', ') : undefined,
+     boxShadow: boxShadow.length > 0 ? boxShadow.join(', ') : undefined,
+     filter: filter.length > 0 ? filter.join(' ') : undefined,
+     backdropFilter: backdrop.length > 0 ? backdrop.join(' ') : undefined,
+     WebkitBackdropFilter: backdrop.length > 0 ? backdrop.join(' ') : undefined,
+     mixBlendMode: props.blend === 'normal' ? undefined : (props.blend as CSSProperties['mixBlendMode']),
+     overflow: props.clip || props.mask ? 'hidden' : undefined,
+     ...dashedStroke(props.strokes),
+     ...layoutStyle(props.layout)
+   } as CSSProperties
+ }
+

