+               {row.children > 0 && !query ? (
+                 <button
+                   onClick={() => toggle(id)}
+                   aria-label={collapsed.has(id) ? 'Expand' : 'Collapse'}
+                   className="w-4 h-4 shrink-0 grid place-items-center text-fg-muted hover:text-fg"
