+               )}
+               <CanvasGlyph
+                 name={layerGlyph(row.shape)}
+                 className={`w-3.5 h-3.5 shrink-0 ${active ? 'text-fg' : 'text-fg-muted'}`}
+               />
+               {renaming === id ? (
+                 <input
+                   autoFocus
+                   defaultValue={layerName(row.shape)}
+                   onBlur={event => {
+                     const name = event.target.value.trim()
